{
  "root_cause": "The modal's focus trap only returns focus to the modal element when focus leaves (via focusin event), but does not wrap Tab/Shift+Tab at the boundaries of the focusable elements within the modal. This causes Shift+Tab from the first focusable element (close button) to move focus to the opener button outside the modal, violating WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order).",
  "repair_strategy": "Add a keydown listener on the modal element to intercept Tab and Shift+Tab keys. When Shift+Tab is pressed and the active element is the close button, prevent default and focus the delete button. When Tab is pressed and the active element is the delete button, prevent default and focus the close button. Bind this listener when the modal is shown (with focus) and unbind when hidden or disposed.",
  "edits": [
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "  constructor(element, config) {
    super(element)

    this._config = this._getConfig(config)
    this._dialog = SelectorEngine.findOne(SELECTOR_DIALOG, this._element)
    this._backdrop = this._initializeBackDrop()
    this._isShown = false
    this._ignoreBackdropClick = false
    this._isTransitioning = false
    this._scrollBar = new ScrollBarHelper()
  }",
      "after": "  constructor(element, config) {
    super(element)

    this._config = this._getConfig(config)
    this._dialog = SelectorEngine.findOne(SELECTOR_DIALOG, this._element)
    this._backdrop = this._initializeBackDrop()
    this._isShown = false
    this._ignoreBackdropClick = false
    this._isTransitioning = false
    this._scrollBar = new ScrollBarHelper()
    this._tabTrapHandler = null
  }"
    },
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "  _resetAdjustments() {
    this._element.style.paddingLeft = ''
    this._element.style.paddingRight = ''
  }

  _initializeBackDrop() {
    return new Backdrop({
      isVisible: Boolean(this._config.backdrop), // 'static' option will be translated to true, and booleans will keep their value
      isAnimated: this._isAnimated()
    })
  }",
      "after": "  _resetAdjustments() {
    this._element.style.paddingLeft = ''
    this._element.style.paddingRight = ''
  }

  _bindTabTrap() {
    const handler = (event) => {
      if (event.key === 'Tab') {
        const first = this._element.querySelector('#confirm-close');
        const last = this._element.querySelector('#confirm-delete');
        if (!first || !last) return;
        if (event.shiftKey) {
          if (document.activeElement === first) {
            event.preventDefault();
            last.focus();
          }
        } else {
          if (document.activeElement === last) {
            event.preventDefault();
            first.focus();
          }
        }
      }
    };
    this._tabTrapHandler = handler;
    this._element.addEventListener('keydown', handler);
  }

  _unbindTabTrap() {
    if (this._tabTrapHandler) {
      this._element.removeEventListener('keydown', this._tabTrapHandler);
      this._tabTrapHandler = null;
    }
  }

  _initializeBackDrop() {
    return new Backdrop({
      isVisible: Boolean(this._config.backdrop), // 'static' option will be translated to true, and booleans will keep their value
      isAnimated: this._isAnimated()
    })
  }"
    },
    {
