  "expected_accessibility_effect": "Shift+Tab from the close button will now wrap to the delete button, and Tab from the delete button will wrap to the close button, maintaining keyboard focus trapped within the modal and satisfying WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order).",
  "functional_risks": [
    "Potential conflict with other custom keydown handlers on the modal.",
    "If the close or delete button IDs change, the wrapper may fail silently.",
    "If the modal is rendered without those buttons, no wrapping occurs but focus behavior remains as before."
  ],
  "verification_requirements": [
    "Verify that Tab navigation loops from close button → input → cancel → delete button → close button.",
    "Verify that Shift+Tab navigation loops in reverse order.",
    "Confirm that Escape key still closes the modal.",
    "Confirm that clicking the modal backdrop still closes the modal.",
    "Ensure focus returns to the opener button after modal is closed."
  ]
}
